'use client';

// import Link from 'next/link';
import React, { useState } from 'react';
import { useRouter } from 'next/navigation';

import { Routes } from '../../routes';
import { components } from '../../components';
import {
  requestAuthentication,
  verifyAuthentication,
} from '@/data/authentication';
import { Alert, Box, CircularProgress, Stack } from '@mui/material';
import Snackbar, { SnackbarCloseReason } from '@mui/material/Snackbar';
import { useDeviceDetect } from '@/hooks/useDeviceDetect';
import { stores } from '@/stores';
import { validPhoneNumber } from '@/utils/phoneNumber_helper';
import { LocalStorageService } from '@/storages/local_storage_service';
import { AppLogo } from '@/components/invest/AppLogo';

export const SignIn: React.FC = () => {
  const { isDesktop } = useDeviceDetect();
  const { setUser } = stores.useUserStore();
  const [open, setOpen] = useState<boolean>(false);
  const router = useRouter();
  // const [rememberMe, setRememberMe] = useState(false);
  const [inSend, toogleInSend] = useState<boolean>(false);
  const [stepper, changeStepper] = useState<number>(0);
  const [phoneNumber, setPhoneNumber] = useState<string>('');
  const [messageError, setMessageError] = useState<string>('');
  const [otp, setOtp] = useState<string>('');
  const renderHeader = () => {
    return <components.Header showGoBack={true} />;
  };

  const handleClose = (
    event: React.SyntheticEvent | Event,
    reason?: SnackbarCloseReason,
  ) => {
    event.preventDefault();
    if (reason === 'clickaway') {
      return;
    }

    setOpen(false);
  };

  const handleAuthentification = async () => {
    if (
      phoneNumber.trim().length >= 8 &&
      phoneNumber.trim().indexOf('+') === -1 &&
      validPhoneNumber(phoneNumber.trim())
    ) {
      toogleInSend(true);
      try {
        const response = await requestAuthentication(phoneNumber.trim());
        if (response.etat) {
          changeStepper(1);
        }
      } catch (error) {
        setMessageError("Une erreur s'est produite");
        setOpen(true);
      }
      toogleInSend(false);
    } else {
      setMessageError('Entrer un numero valide');
      setOpen(true);
    }
  };
  const handleVerificationAuthentification = async () => {
    if (phoneNumber.trim().length === 10 && otp.trim().length === 4) {
      toogleInSend(true);
      try {
        const response = await verifyAuthentication(phoneNumber.trim(), otp);
        if (response.etat) {
          setUser(response.result.client);
          const redirection = LocalStorageService.getLocationRedirection();
          LocalStorageService.saveLocationRedirection('');
          router.push(redirection || Routes.HOME);
        } else {
          setMessageError(response.error![0]);
          setOpen(true);
        }
      } catch (error) {
        setMessageError("Une erreur s'est produite");
        setOpen(true);
      }
      toogleInSend(false);
    } else {
      setMessageError('Entrer un code valide');
      setOpen(true);
    }
  };

  const resendOtp = (event: React.MouseEvent<HTMLSpanElement>): void => {
    event.preventDefault();
    handleAuthentification();
  };

  const renderContent = () => {
    return (
      <main
        className="scrollable container max-screen-width"
        style={{ paddingTop: 10 }}
      >
        <section
          style={{
            height: '100%',
            display: 'flex',
            justifyContent: 'center',
            flexDirection: 'column',
            borderRadius: '28px',
            background: [
              'radial-gradient(60% 45% at 100% 0%, rgba(252, 197, 94, 0.35) 0%, rgba(252, 197, 94, 0) 70%)',
              'radial-gradient(55% 40% at 0% 100%, rgba(252, 197, 94, 0.18) 0%, rgba(252, 197, 94, 0) 70%)',
              'linear-gradient(160deg, #1e2538 0%, #2b3554 55%, #1e2538 100%)',
            ].join(', '),
            boxShadow: '0 24px 60px -24px rgba(30, 37, 56, 0.55)',
          }}
          className="container"
        >
          <div
            style={{
              display: 'flex',
              justifyContent: 'center',
              marginBottom: 16,
            }}
          >
            <AppLogo size={48} light />
          </div>

          <h1
            style={{
              marginBottom: 16,
              textAlign: 'center',
              color: 'var(--white-color)',
            }}
          >
            Bienvenue à vous !
          </h1>
          <span
            className="t16"
            style={{ marginBottom: 32, textAlign: 'center', color: '#c8cdd9' }}
          >
            {stepper === 0
              ? 'Veuillez entrer votre numero de téléphone nous vous enverons un code OTP pour valider votre compte'
              : 'Veuillez entrer le code OTP qui vous a été envoyé sur votre ' +
                phoneNumber}
          </span>

          {/* INPUT FIELDS */}
          <section>
            {stepper === 0 && (
              <components.InputField
                inputType="tel"
                type="tel"
                placeholder="0XXXXXXX"
                value={phoneNumber}
                containerStyle={{ marginBottom: 16 }}
                onChange={(e) => {
                  setPhoneNumber(e.target.value);
                }}
              />
            )}

            {stepper === 1 && (
              <Stack
                direction="row"
                alignItems="center"
                justifyContent="center"
                sx={{ width: '100%', mb: 2 }}
              >
                <components.OTPInput value={otp} onChange={setOtp} length={4} />
              </Stack>
            )}

            {/* <components.InputField
              inputType="password"
              placeholder="Enter your password"
              containerStyle={{ marginBottom: 16 }}
            /> */}
          </section>

          {/* REMEMBER ME */}
          <section
            style={{
              marginBottom: 32,
              display: 'flex',
              flexDirection: 'row',
              justifyContent: stepper === 1 ? 'space-between' : 'flex-end',
            }}
          >
            {stepper === 1 && (
              <div
                style={{
                  gap: '10px',
                  display: 'flex',
                  flexDirection: 'row',
                  alignItems: 'center',
                }}
                className="clickable"
                onClick={() => changeStepper(0)}
              >
                {/* <div
                style={{
                  width: '18px',
                  height: '18px',
                  borderRadius: 5,
                  backgroundColor: 'var(--white-color)',
                  display: 'flex',
                  justifyContent: 'center',
                  alignItems: 'center',
                  border: '1px solid #C8CDD9',
                }}
              >
                {rememberMe && <svg.InputCheckSvg />}
              </div> */}
                <span
                  className="t16"
                  style={{ lineHeight: 1.2, color: '#c8cdd9' }}
                >
                  Changer numéro
                </span>
              </div>
            )}

            {stepper === 1 && (
              <span
                className="t16 main-color clickable"
                onClick={resendOtp}
                style={{ color: 'var(--accent-color)', lineHeight: 1.2 }}
              >
                Renvoyez le code !
              </span>
            )}
          </section>

          {/* SIGN IN BUTTON */}
          <section style={{ marginBottom: 24 }}>
            {inSend ? (
              <Box
                component="div"
                sx={{
                  display: 'flex',
                  flexDirection: 'row',
                  alignItems: 'center',
                  justifyContent: 'center',
                  height: 50,
                  width: '100%',
                }}
              >
                <CircularProgress
                  size={30}
                  sx={{ color: 'var(--accent-color)' }}
                />
              </Box>
            ) : (
              <components.Button
                label={stepper === 0 ? 'Connexion/Inscription' : 'Valider'}
                onClick={(e) => {
                  e.preventDefault();
                  if (stepper === 0) {
                    handleAuthentification();
                  } else {
                    handleVerificationAuthentification();
                  }
                }}
              />
            )}
          </section>
        </section>
      </main>
    );
  };

  const renderHeight = () => {
    return <div style={{ height: 30 }} />;
  };

  return (
    <components.Screen>
      <components.Background />
      {!isDesktop && renderHeader()}
      {renderContent()}
      {renderHeight()}
      <Snackbar
        anchorOrigin={{ vertical: 'top', horizontal: 'right' }}
        open={open}
        autoHideDuration={5000}
        onClose={handleClose}
      >
        <Alert
          onClose={handleClose}
          severity="warning"
          variant="filled"
          sx={{ width: '100%' }}
        >
          {messageError}
        </Alert>
      </Snackbar>
    </components.Screen>
  );
};
